args<-commandArgs(TRUE);P<-normalizePath(args[1]);W<-file.path(P,'work/2026-10-29-journal-bulk-four');library(ggplot2);library(grid);library(jsonlite)
ink<-'#30343B'
theme_set(theme_classic(base_family='Arial',base_size=7)+theme(axis.text=element_text(size=7,colour=ink),axis.title=element_text(size=7),legend.text=element_text(size=7),legend.title=element_text(size=7,margin=margin(r=5)),strip.text=element_text(size=7),plot.title=element_text(size=7,face='bold'),plot.tag=element_text(size=9,face='bold'),axis.line=element_line(linewidth=.25),axis.ticks=element_line(linewidth=.25),plot.margin=margin(3,3,3,3)))
for(key in c('bile','lipid','clusters','deswan')){
 w<-file.path(W,key);q<-fromJSON(file.path(w,'input-qc.json'));glist<-list();metrics<-list();put<-function(x)glist[[length(glist)+1]]<<-x
 txt<-function(t,x,y,size=7,just='left',rot=0,bold=FALSE)put(textGrob(t,unit(x,'mm'),unit(y,'mm'),just=just,rot=rot,gp=gpar(fontfamily='Arial',fontsize=size,fontface=if(bold)'bold'else'plain',col=ink)))
 seg<-function(x1,y1,x2,y2,col=ink,lwd=.6)put(segmentsGrob(unit(x1,'mm'),unit(y1,'mm'),unit(x2,'mm'),unit(y2,'mm'),gp=gpar(col=col,lwd=lwd)))
 rect<-function(x,y,ww,hh,fill,col=NA,lwd=.5)put(rectGrob(unit(x,'mm'),unit(y,'mm'),unit(ww,'mm'),unit(hh,'mm'),just=c('left','bottom'),gp=gpar(fill=fill,col=col,lwd=lwd)))
 heat<-function(mat,x,y,cell,colfun,id){nr<-nrow(mat);nc<-ncol(mat);ij<-expand.grid(row=1:nr,col=1:nc);values<-as.vector(mat);gr<-rectGrob(x=unit((ij$col-.5)*cell,'mm'),y=unit((nr-ij$row+.5)*cell,'mm'),width=unit(cell,'mm'),height=unit(cell,'mm'),gp=gpar(fill=colfun(values),col='white',lwd=.35));put(gTree(children=gList(gr),vp=viewport(x=unit(x,'mm'),y=unit(y,'mm'),width=unit(nc*cell,'mm'),height=unit(nr*cell,'mm'),just=c('left','bottom'),name=paste0('matrix-',id))));metrics[[length(metrics)+1]]<<-list(matrix_id=id,panel_id=id,rows=nr,columns=nc,matrix_rows=nr,matrix_columns=nc,body_width_mm=nc*cell,body_height_mm=nr*cell,cell_width_mm=cell,cell_height_mm=cell,measurement_method='final_body_viewports_mm')}
 ramp<-function(cols,lim){pal<-colorRampPalette(cols)(256);function(v)pal[pmin(256,pmax(1,round((v-lim[1])/diff(lim)*255)+1))]}
 colorbar<-function(x,y,hh,fun,lims,title){for(i in 0:127)rect(x,y+hh*i/128,3,hh/128+.015,fun(lims[1]+diff(lims)*i/127));for(v in pretty(lims,n=4)){if(v>=lims[1]&&v<=lims[2]){yy<-y+hh*(v-lims[1])/diff(lims);seg(x+3,yy,x+4,yy);txt(format(v,trim=TRUE),x+5,yy)}};txt(title,x,y+hh+4)}
 if(key=='bile'){
  d<-readRDS(file.path(w,'data.rds'));m<-xtabs(fraction~aminoacid+tissue,d$combined)[d$aas,d$tissues];n<-xtabs(log_count~aminoacid+OH,d$counts)[d$aas,c('2','3')];fun1<-ramp(c('#F7F8F7','#77CBB5','#357C9D'),c(0,max(n)));fun2<-ramp(c('#F7F8F7','#65C7B6','#27678D'),c(0,max(m)));put(rectGrob(gp=gpar(fill='white',col=NA)));heat(n,25,23,4,fun1,'oh-counts');heat(m,39,23,4,fun2,'tissue-fractions');for(i in seq_along(d$aas))txt(gsub('Ile/Leu','Leu / Ile',d$aas[i],fixed=TRUE),23,23+(length(d$aas)-i+.5)*4,just='right')
  txt('a',2,114,9,bold=TRUE);txt('OH class',29,112,just='centre');txt('b',36,114,9,bold=TRUE);txt('Tissue / biofluid',67,112,just='centre');txt(c('2-OH','3-OH'),c(27,31),21,just='right',rot=90)
  labs<-tools::toTitleCase(d$tissues);labs[labs=='Upper Digestive Tract']<-'Upper GI tract';for(j in seq_along(labs))txt(labs[j],39+(j-.5)*4,21,just='right',rot=90)
  colorbar(103,76,24,fun1,c(0,max(n)),'log(1 + matches)');colorbar(103,34,24,fun2,c(0,max(m)),'Summed fractions');g<-gTree(children=do.call(gList,glist))
 }else if(key=='clusters'){
  d<-readRDS(file.path(w,'data.rds'));ord<-d$hc$order;ages<-seq(30,75,2.5);m<-as.matrix(d$center[ord,as.character(ages)]);fun<-ramp(c('#4D78B2','#F7F7F5','#ECA35D'),c(-2,2));put(rectGrob(gp=gpar(fill='white',col=NA)));heat(m,22,68,4,fun,'cluster-centers');yy<-setNames(68+(11-seq_along(ord)+.5)*4,ord)
  # Actual complete-linkage dendrogram from the retained 91-point centers.
  dx<-function(h)19-12*h/max(d$hc$height);nodeY<-numeric(10);nodeH<-numeric(10)
  for(i in 1:10){ch<-d$hc$merge[i,];ys<-sapply(ch,function(v)if(v<0)yy[as.character(-v)]else nodeY[v]);hs<-sapply(ch,function(v)if(v<0)0 else nodeH[v]);xx<-dx(d$hc$height[i]);seg(xx,ys[1],xx,ys[2],col='#73808B');for(j in 1:2)seg(xx,ys[j],dx(hs[j]),ys[j],col='#73808B');nodeY[i]<-mean(ys);nodeH[i]<-d$hc$height[i]}
  for(k in ord){y<-yy[as.character(k)];co<-d$comp[d$comp$cluster==k,];xx<-102;for(i in 1:nrow(co)){ww<-30*co$fraction[i];if(ww>0)rect(xx,y-1.65,ww,3.3,d$ocol[as.character(co$class[i])]);xx<-xx+ww};v<-d$fi$correlation[d$fi$cluster==k];b<-boxplot.stats(v)$stats;scale<-function(v)138+(v+1)*16;seg(scale(b[1]),y,scale(b[5]),y,col='#538F88');seg(scale(b[1]),y-1,scale(b[1]),y+1,col='#538F88');seg(scale(b[5]),y-1,scale(b[5]),y+1,col='#538F88');rect(scale(b[2]),y-1.2,scale(b[4])-scale(b[2]),2.4,'#D6EDE6','#538F88');seg(scale(b[3]),y-1.2,scale(b[3]),y+1.2,col='#2E645F',lwd=.8);txt(as.character(k),175,y,just='centre')}
  txt('a',2,118,9,bold=TRUE);txt('Cluster centers',22,118,bold=TRUE);txt('Composition (%)',117,118,just='centre');txt('Spearman r',154,118,just='centre');txt('Cluster',175,118,just='centre')
  for(age in c(30,40,50,60,70,75)){xx<-22+(match(age,ages)-.5)*4;seg(xx,68,xx,66.8);txt(as.character(age),xx,64.8,just='centre')};txt('Age (years)',60,60.5,just='centre')
  for(v in c(0,50,100))txt(as.character(v),102+30*v/100,65,just='centre');for(v in c(-1,0,1))txt(as.character(v),138+(v+1)*16,65,just='centre')
  txt('z-score',4,56);for(i in 0:99)rect(17+i*.35,54.7,.36,2,fun(-2+4*i/99));for(v in c(-2,0,2))txt(as.character(v),17+(v+2)/4*35,51.7,just='centre')
  for(i in 1:10){x<-5+((i-1)%%5)*35.6;y<-if(i<=5)46 else 40;rect(x,y-1,2,2,d$ocol[i]);txt(d$clabel[i],x+3,y)}
  cs<-read.csv(file.path(P,'results/plot_data','journal_clusters_20261029_centers.csv'));sel<-c(2,4,5);for(i in 1:3){k<-sel[i];z<-cs[cs$cluster==k,];n<-sum(d$fi$cluster==k);pp<-ggplot(z,aes(age,z))+geom_hline(yintercept=0,colour='#CDD3D7',linewidth=.25)+geom_line(colour=c('#378F92','#8275BD','#DC9B51')[i],linewidth=.7)+scale_x_continuous(breaks=c(30,45,60,75))+labs(x='Age (years)',y=if(i==1)'Mean z-score'else NULL,title=paste0('Cluster ',k,'  |  ',format(n,big.mark=','),' features'))+theme_classic(base_family='Arial',base_size=7)+theme(axis.text=element_text(size=7,colour=ink),axis.title=element_text(size=7),plot.title=element_text(size=7,face='bold'),plot.margin=margin(1,4,1,1),axis.line=element_line(linewidth=.25));gg<-ggplotGrob(pp);put(gTree(children=gList(gg),vp=viewport(x=unit(3+(i-1)*60,'mm'),y=unit(2,'mm'),width=unit(58,'mm'),height=unit(33,'mm'),just=c('left','bottom'))))};g<-gTree(children=do.call(gList,glist))
 }else{p<-readRDS(file.path(w,'plot.rds'));g<-patchwork::patchworkGrob(p)}
 labels<-character();fix<-function(x){if(inherits(x,'text')){if(is.expression(x$label))x$label<-vapply(x$label,function(z)paste(deparse(z),collapse=''),character(1));x$gp$fontfamily<-'Arial';x$gp$cex<-1;x$gp$fontsize<-if(is.null(x$gp$fontsize))7 else ifelse(abs(x$gp$fontsize-9)<.01,9,7);labels<<-c(labels,as.character(x$label))};if(length(x$grobs))x$grobs<-lapply(x$grobs,fix);if(length(x$children))x$children<-do.call(gList,lapply(x$children,fix));x}
 ragg::agg_png(file.path(w,'exploratory.png'),width=q$width_mm,height=q$height_mm,units='mm',res=200,background='white');g<-fix(g);grid.newpage();grid.draw(g);grid.force();g<-grid.grab(wrap=TRUE);g<-fix(g);dev.off();saveRDS(g,file.path(w,'composed-vector-grob.rds'));p<-ggplotify::as.ggplot(g)+theme(plot.margin=margin(0,0,0,0),text=element_text(family='Arial',size=7));saveRDS(p,file.path(w,'render-object.rds'));write_json(list(labels=unique(labels[!is.na(labels)&nzchar(trimws(labels))])),file.path(w,'text-manifest.json'),pretty=TRUE,auto_unbox=TRUE);write_json(metrics,file.path(w,'native-cell-metrics.json'),pretty=TRUE,auto_unbox=TRUE,digits=NA)
}
